package com.fasterxml.jackson.dataformat.xml.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.base.GeneratorBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.dataformat.xml.XmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.util.DefaultXmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.util.StaxUtil;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import javax.xml.namespace.QName;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamWriter;
import org.codehaus.stax2.XMLStreamWriter2;
import org.codehaus.stax2.ri.Stax2WriterAdapter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.*;

public class ToXmlGenerator_writeNumber_TriageGen1Test {

    private IOContext ioContext;
    private ObjectCodec codec;
    private XMLStreamWriter xmlStreamWriter;
    private ToXmlGenerator generator;
    private QName testQName;

    @Before
    public void setUp() {
        ioContext = mock(IOContext.class);
        codec = mock(ObjectCodec.class);
        xmlStreamWriter = mock(XMLStreamWriter.class);
        generator = spy(new ToXmlGenerator(ioContext, 0, 0, codec, xmlStreamWriter));
        testQName = new QName("http://test.com", "testElement");
    }

    @Test
    public void testWriteNumber_AsAttribute() throws Exception {
        // Arrange
        generator.setNextName(testQName);
        generator.setNextIsAttribute(true);
        long value = 123L;

        // Act
        generator.writeNumber(value);

        // Assert
        verify(xmlStreamWriter).writeLongAttribute(isNull(), eq("http://test.com"), eq("testElement"), eq(value));
    }

    @Test
    public void testWriteNumber_AsUnwrapped() throws Exception {
        // Arrange
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        // Mock checkNextIsUnwrapped to return true
        doReturn(true).when(generator).checkNextIsUnwrapped();
        long value = 456L;

        // Act
        generator.writeNumber(value);

        // Assert
        verify(xmlStreamWriter).writeLong(value);
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    @Test
    public void testWriteNumber_AsLeafElementWithPrettyPrinter() throws Exception {
        // Arrange
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();

        PrettyPrinter mockPrettyPrinter = mock(PrettyPrinter.class);
        generator.setPrettyPrinter(mockPrettyPrinter);
        long value = 789L;

        // Act
        generator.writeNumber(value);

        // Assert
        verify(mockPrettyPrinter).writeLeafElement(eq(xmlStreamWriter), eq("http://test.com"), eq("testElement"), eq(value));
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    @Test
    public void testWriteNumber_AsStandardElementNoPrettyPrinter() throws Exception {
        // Arrange
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();
        generator.setPrettyPrinter(null);
        long value = 101L;

        // Act
        generator.writeNumber(value);

        // Assert
        verify(xmlStreamWriter).writeStartElement("http://test.com", "testElement");
        verify(xmlStreamWriter).writeLong(value);
        verify(xmlStreamWriter).writeEndElement();
    }

    @Test
    public void testWriteNumber_MissingNameThrowsException() throws Exception {
        // Arrange
        // _nextName is null by default
        doThrow(new RuntimeException("Missing Name")).when(generator).handleMissingName();

        // Act & Assert
        try {
            generator.writeNumber(1L);
        } catch (RuntimeException e) {
            // Expected
        }
        verify(generator).handleMissingName();
    }

    @Test(expected = Exception.class)
    public void testWriteNumber_XmlStreamExceptionHandling() throws Exception {
        // Arrange
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();

        // Force XMLStreamException
        doThrow(new XMLStreamException("Stream Error")).when(xmlStreamWriter).writeStartElement(any(), any());
        // Note: In the actual code, writeLong follows writeStartElement, 
        // but if writeStartElement fails, it goes to catch.
        // If we want to hit the catch block specifically via the code path:
        // We'll use the path that calls writeLong directly if possible or trigger via writeStartElement

        // To ensure we hit the catch block in the provided logic:
        // Let's make writeLong throw it instead
        doThrow(new XMLStreamException("Stream Error")).when(xmlStreamWriter).writeLong(anyLong());

        // We need to make sure it goes to the writeLong branch
        generator.setNextIsAttribute(false);
        doReturn(true).when(generator).checkNextIsUnwrapped();

        // Act
        generator.writeNumber(1L);
    }
}
